using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Drawing;
using System.Windows.Forms;
using System.Collections.Generic;
namespace JingFamily {
 public class ReviewItem { public string PersonId,Category,Message; public ReviewItem(string id,string category,string message){PersonId=id;Category=category;Message=message;} }
 public class Reminder {public string PersonId,Kind;public DateTime Date;public int Years;}
 public static class Workshop {
  public static FamilyData Clone(){return Store.Deserialize(Store.Serialize(Store.Data));}
  public static List<ReviewItem> Review(FamilyData d,bool missing){var list=new List<ReviewItem>();foreach(var p in d.People){if(missing){var fields=new List<string>();if(p.Birth=="")fields.Add("出生日期");if(p.Place=="")fields.Add("籍贯");if(p.Generation=="")fields.Add("字辈");if(p.Biography=="")fields.Add("生平");if(p.FatherId==""&&p.MotherId=="")fields.Add("父母关系");if(fields.Count>0)list.Add(new ReviewItem(p.Id,"待补全",String.Join("、",fields)));}else{
   if(p.Birth!=""&&Store.DateStart(p.Birth)>DateTime.Today)list.Add(new ReviewItem(p.Id,"日期待核实","出生日期晚于今天"));if(p.Death!=""&&Store.DateStart(p.Death)>DateTime.Today)list.Add(new ReviewItem(p.Id,"日期待核实","去世日期晚于今天"));
   foreach(string id in new[]{p.FatherId,p.MotherId}){var parent=d.People.Find(x=>x.Id==id);if(parent==null||parent.Birth==""||p.Birth=="")continue;int low=Store.DateStart(p.Birth).Year-Store.DateEnd(parent.Birth).Year,high=Store.DateEnd(p.Birth).Year-Store.DateStart(parent.Birth).Year;if(high<12||low>75)list.Add(new ReviewItem(p.Id,"亲子日期待核实",parent.Name+"在该成员出生时约 "+low+"～"+high+" 岁。请人工核实。"));}
  }}return list;}
  public static IEnumerable<IGrouping<string,Person>> Duplicates(FamilyData d){return d.People.GroupBy(p=>String.Concat(p.Name.Where(c=>!Char.IsWhiteSpace(c))).ToUpperInvariant()).Where(g=>g.Count()>1);}
  public static DateTime NextDate(string text,DateTime today){var d=Store.DateStart(text);var next=new DateTime(today.Year,d.Month,Math.Min(d.Day,DateTime.DaysInMonth(today.Year,d.Month)));if(next<today.Date){int year=today.Year+1;next=new DateTime(year,d.Month,Math.Min(d.Day,DateTime.DaysInMonth(year,d.Month)));}return next;}
  public static List<Reminder> Reminders(FamilyData d,DateTime today,int days){var list=new List<Reminder>();foreach(var p in d.People){string date=p.Death==""?p.Birth:p.Death;if(date.Length!=10||Store.DateStart(date)>today)continue;var next=NextDate(date,today);if((next-today.Date).Days<=days)list.Add(new Reminder{PersonId=p.Id,Kind=p.Death==""?"生日":"忌日",Date=next,Years=next.Year-Store.DateStart(date).Year});}return list.OrderBy(x=>x.Date).ThenBy(x=>x.Kind).ToList();}
  public static FamilyData AddRelative(string anchorId,string kind,string name,string birth,string gender,bool asFather){var d=Clone();var a=d.People.Find(x=>x.Id==anchorId);if(a==null)throw new Exception("请选择当前成员。");var p=new Person{Name=name.Trim(),Birth=birth.Trim(),Gender=gender};if(kind=="父亲"){if(a.FatherId!="")throw new Exception("已记录父亲，请到成员档案编辑。");p.Gender="男";a.FatherId=p.Id;}else if(kind=="母亲"){if(a.MotherId!="")throw new Exception("已记录母亲，请到成员档案编辑。");p.Gender="女";a.MotherId=p.Id;}else if(kind=="配偶"){p.Spouses.Add(a.Id);a.Spouses.Add(p.Id);}else if(kind=="儿子"||kind=="女儿"){p.Gender=kind=="儿子"?"男":"女";if(asFather)p.FatherId=a.Id;else p.MotherId=a.Id;}else if(kind=="兄弟"||kind=="姐妹"){if(a.FatherId==""&&a.MotherId=="")throw new Exception("请先为当前成员记录至少一位父母，再添加兄弟姐妹。");p.Gender=kind=="兄弟"?"男":"女";p.FatherId=a.FatherId;p.MotherId=a.MotherId;}else throw new Exception("关系类型无效。");d.People.Add(p);Store.Validate(d);return d;}
  public static FamilyData Merge(string keepId,string removeId,out string summary){if(keepId==removeId)throw new Exception("请选择两份不同档案。");var d=Clone();var keep=d.People.Find(x=>x.Id==keepId);var other=d.People.Find(x=>x.Id==removeId);if(keep==null||other==null)throw new Exception("成员不存在。");if(Store.IsAncestor(d,keepId,removeId)||Store.IsAncestor(d,removeId,keepId)||keep.Spouses.Contains(removeId))throw new Exception("两人已记录为直系亲属或配偶，不能直接合并，请先人工核实关系。");
   var conflicts=new List<string>();string[] fields={"Name","Gender","Birth","Death","Place","Address","Phone","Occupation","Generation","FatherId","MotherId"};foreach(string key in fields){var field=typeof(Person).GetField(key);string a=(string)field.GetValue(keep),b=(string)field.GetValue(other);if((a==""||(key=="Gender"&&a=="未知"))&&b!="")field.SetValue(keep,b);else if(b!=""&&a!=b){string label=new Dictionary<string,string>{{"Name","姓名"},{"Gender","性别"},{"Birth","出生"},{"Death","去世"},{"Place","籍贯"},{"Address","住址"},{"Phone","联系方式"},{"Occupation","职业"},{"Generation","字辈"},{"FatherId","父亲编号"},{"MotherId","母亲编号"}}[key];conflicts.Add(label+"：保留「"+a+"」，原另一档案为「"+b+"」");}}
   if(keep.Biography=="")keep.Biography=other.Biography;else if(other.Biography!=""&&keep.Biography!=other.Biography)keep.Biography+="\r\n\r\n【另一档案生平】\r\n"+other.Biography;if(conflicts.Count>0)keep.Biography+="\r\n\r\n【合并差异记录】\r\n"+String.Join("\r\n",conflicts);
   if(keep.Portrait=="")keep.Portrait=other.Portrait;else if(other.Portrait!=""&&other.Portrait!=keep.Portrait)d.Documents.Add(new Document{Title=other.Name+" · 合并保留头像",PersonId=keepId,File=other.Portrait,Notes="合并档案时保留另一头像"});keep.Spouses=keep.Spouses.Concat(other.Spouses).Where(x=>x!=keepId&&x!=removeId).Distinct().ToList();d.People.Remove(other);
   foreach(var p in d.People){if(p.FatherId==removeId)p.FatherId=keepId;if(p.MotherId==removeId)p.MotherId=keepId;p.Spouses=p.Spouses.Select(x=>x==removeId?keepId:x).Distinct().ToList();}foreach(string id in keep.Spouses){var p=d.People.Find(x=>x.Id==id);if(!p.Spouses.Contains(keepId))p.Spouses.Add(keepId);}foreach(var e in d.Events)if(e.PersonId==removeId)e.PersonId=keepId;foreach(var doc in d.Documents)if(doc.PersonId==removeId)doc.PersonId=keepId;foreach(var t in d.Tasks)if(t.PersonId==removeId)t.PersonId=keepId;Store.Validate(d);summary="保留："+keep.Name+" ["+keepId+"]\r\n移除另一档案："+other.Name+" ["+removeId+"]\r\n亲属、事件、资料和待办关联将转移到保留档案。\r\n空字段自动补齐，冲突字段按保留档案处理，差异写入生平。\r\n"+(conflicts.Count==0?"没有字段冲突。":String.Join("\r\n",conflicts))+"\r\n\r\n确认合并前会创建完整备份。";return d;}
  public static FamilyData Bulk(IEnumerable<string> ids,string field,string value,bool overwrite){if(!new[]{"Generation","Place","Occupation"}.Contains(field)||String.IsNullOrWhiteSpace(value))throw new Exception("请填写要设置的内容。");var selected=new HashSet<string>(ids);if(selected.Count==0)throw new Exception("请勾选至少一位成员。");var d=Clone();var f=typeof(Person).GetField(field);foreach(var p in d.People.Where(x=>selected.Contains(x.Id)))if(overwrite||String.IsNullOrWhiteSpace((string)f.GetValue(p)))f.SetValue(p,value.Trim());Store.Validate(d);return d;}
  public static FamilyData Previous(){string f=Store.FilePath+".previous";if(!File.Exists(f))throw new Exception("还没有上一次保存可恢复。");var d=Store.Deserialize(File.ReadAllBytes(f));Store.Validate(d);foreach(string media in d.People.Select(x=>x.Portrait).Concat(d.Documents.Select(x=>x.File)).Where(x=>x!=""))if(!File.Exists(Path.Combine(Store.Root,media)))throw new Exception("上次保存引用的附件缺失，请从完整 ZIP 备份恢复。");return d;}
 }
 public class QuickRelativeEditor:Editor {
  string anchor;ComboBox kind,gender,role;TextBox name,birth;
  public QuickRelativeEditor(string id):base("为「"+Store.Name(id)+"」添加亲属",660,530){anchor=id;kind=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};kind.Items.AddRange(new[]{"父亲","母亲","配偶","儿子","女儿","兄弟","姐妹"});kind.SelectedIndex=2;Field("新增关系",kind);name=TextField("姓名 *","");gender=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};gender.Items.AddRange(new[]{"未知","男","女"});gender.SelectedIndex=0;Field("性别",gender);birth=TextField("出生日期","");role=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};role.Items.AddRange(new[]{"父亲","母亲"});role.SelectedIndex=Store.Get(id).Gender=="女"?1:0;Field("当前成员作为",role);Field("说明",Ui.Label("添加子女时指定当前成员作为父亲或母亲。\n其他关系忽略该选项。完整档案可在保存后继续编辑。",9),75);}
  protected override bool Commit(){Store.Commit(Workshop.AddRelative(anchor,kind.Text,name.Text,birth.Text,gender.Text,role.SelectedIndex==0));return true;}
 }
 public class TaskEditor:Editor {
  string id;TextBox title,due,notes;ComboBox person;CheckBox done;
  public TaskEditor(ResearchTask task):base(task==null?"添加编修待办":"编辑编修待办",650,550){var t=task??new ResearchTask();id=t.Id;title=TextField("标题 *",t.Title);person=PersonField("关联成员",t.PersonId);due=TextField("截止日期",t.Due);Field("格式",Ui.Label("YYYY-MM-DD，或留空",9),30);done=new CheckBox{Text="已完成",Checked=t.Done};Field("状态",done);notes=TextField("线索 / 说明",t.Notes,true);}
  protected override bool Commit(){var d=Workshop.Clone();d.Tasks.RemoveAll(x=>x.Id==id);d.Tasks.Add(new ResearchTask{Id=id,Title=title.Text.Trim(),PersonId=Id(person),Due=due.Text.Trim(),Done=done.Checked,Notes=notes.Text});Store.Commit(d);return true;}
 }
 public class BulkEditor:Editor {
  CheckedListBox people;ComboBox field;TextBox value;CheckBox overwrite;
  public BulkEditor():base("批量完善档案",720,740){field=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};field.Items.AddRange(new[]{"字辈","籍贯","职业"});field.SelectedIndex=0;Field("填写字段",field);value=TextField("统一内容 *","");overwrite=new CheckBox{Text="同时覆盖已有内容（默认仅补空白）"};Field("覆盖方式",overwrite);people=new CheckedListBox{CheckOnClick=true};foreach(var p in Store.Data.People.OrderBy(x=>x.Name))people.Items.Add(new PickItem(p.Id,p.Name+" · "+p.Birth+" · "+p.Place+" · "+p.Generation));Field("勾选成员",people,330);var tools=new FlowLayoutPanel();tools.Controls.Add(Ui.Button("全选",()=>{for(int i=0;i<people.Items.Count;i++)people.SetItemChecked(i,true);}));tools.Controls.Add(Ui.Button("全不选",()=>{for(int i=0;i<people.Items.Count;i++)people.SetItemChecked(i,false);}));Field("选择",tools,50);}
  protected override bool Commit(){var d=Workshop.Bulk(people.CheckedItems.Cast<PickItem>().Select(x=>x.Id),new[]{"Generation","Place","Occupation"}[field.SelectedIndex],value.Text,overwrite.Checked);if(!Ui.Confirm("将修改勾选成员的「"+field.Text+"」。保存前会创建完整备份，是否继续？"))return false;Store.Replace(d,null);return true;}
 }
 public class MergeWindow:Editor {
  ComboBox keep,other;TextBox preview;
  public MergeWindow(string first="",string second=""):base("核实并合并重复档案",820,720){keep=PersonField("保留档案",first);other=PersonField("另一档案",second);var actions=new FlowLayoutPanel();actions.Controls.Add(Ui.Button("预览合并结果",()=>{string summary;Workshop.Merge(Id(keep),Id(other),out summary);preview.Text=summary;},true));Field("核实",actions,50);preview=TextField("合并说明","必须确认两份档案属于同一人。\r\n同名仅是检查线索，不能据此判断为同一人。\r\n\r\n选择保留档案与另一档案，点击「预览合并结果」。",true);Fields.RowStyles[Fields.RowCount-1].Height=350;}
  protected override bool Commit(){string summary;var d=Workshop.Merge(Id(keep),Id(other),out summary);preview.Text=summary;if(!Ui.Confirm(summary+"\r\n\r\n已人工确认是同一人，立即合并？"))return false;Store.Replace(d,null);return true;}
 }
 public class WorkbenchPanel:UserControl {
  Action<string> edit;TabControl tabs;
  public WorkbenchPanel(Action<string> editPerson){edit=editPerson;Dock=DockStyle.Fill;BackColor=Ui.Cream;tabs=new PillTabs{Dock=DockStyle.Fill,Font=Ui.Font(11)};Controls.Add(tabs);RefreshTabs();}
  static string Key(DataGridView g){return g.CurrentRow==null?"":g.CurrentRow.Tag as string??"";}
  FlowLayoutPanel Tools(TabPage page,params Control[] buttons){var f=new FlowLayoutPanel{Dock=DockStyle.Top,Height=57,Padding=new Padding(10,10,0,0)};f.Controls.AddRange(buttons);page.Controls.Add(f);return f;}
  void RefreshTabs(){int index=tabs.SelectedIndex;foreach(TabPage p in tabs.TabPages.Cast<TabPage>().ToArray())p.Dispose();tabs.TabPages.Clear();ReviewTab(true);ReviewTab(false);DuplicateTab();ReminderTab();TaskTab();if(index>=0&&index<tabs.TabCount)tabs.SelectedIndex=index;}
  TabPage Page(string title){var p=new TabPage(title){BackColor=Ui.Cream,Padding=new Padding(8)};tabs.TabPages.Add(p);return p;}
  void ReviewTab(bool missing){var p=Page(missing?"待补全档案":"日期核查");var g=Ui.Grid();Ui.Columns(g,"姓名","类别","需要核实 / 补充的内容");g.Columns[2].FillWeight=300;foreach(var item in Workshop.Review(Store.Data,missing)){int r=g.Rows.Add(Store.Name(item.PersonId),item.Category,item.Message);g.Rows[r].Tag=item.PersonId;}Tools(p,Ui.Button("编辑选中成员",()=>{if(Key(g)!="")edit(Key(g));},true),Ui.Button("刷新检查",RefreshTabs),Ui.Button("导出清单",()=>{string f=Ui.SavePath("CSV 清单|*.csv",missing?"待补全档案.csv":"日期核查.csv");if(f==null)return;var rows=new List<string[]>{new[]{"姓名","类别","说明"}};rows.AddRange(Workshop.Review(Store.Data,missing).Select(x=>new[]{Store.Name(x.PersonId),x.Category,x.Message}));WriteCsv(f,rows);}),Ui.Label(missing?"未知信息可保持空白，无需为了完整而编造。":"仅作核实提示，不自动修改日期。",9));p.Controls.Add(g);g.BringToFront();g.CellDoubleClick+=(s,e)=>{if(e.RowIndex>=0)edit(Key(g));};}
  static void WriteCsv(string path,IEnumerable<string[]> rows){File.WriteAllText(path,String.Join("\r\n",rows.Select(r=>String.Join(",",r.Select(x=>Store.Csv(x.Length>0&&"=+-@".Contains(x[0])?"'"+x:x))))),new UTF8Encoding(true));Ui.Info("清单已导出。");}
  void DuplicateTab(){var p=Page("重复档案核查");var g=Ui.Grid();Ui.Columns(g,"姓名","出生日期","籍贯","编号");foreach(var group in Workshop.Duplicates(Store.Data))foreach(var member in group){int r=g.Rows.Add(member.Name,member.Birth,member.Place,member.Id);g.Rows[r].Tag=member.Id;}Tools(p,Ui.Button("核实并合并",()=>{using(var w=new MergeWindow(Key(g)))if(w.ShowDialog(this)==DialogResult.OK)RefreshTabs();},true),Ui.Button("编辑档案",()=>{if(Key(g)!="")edit(Key(g));}),Ui.Label("列出同名或仅空格不同的档案；同名可能是不同人物。",9));p.Controls.Add(g);g.BringToFront();}
  void ReminderTab(){var p=Page("生日与忌日");var g=Ui.Grid();Ui.Columns(g,"纪念日期","类型","姓名","周年 / 周岁","距今天");var range=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=105};range.Items.AddRange(new[]{"未来 30 天","未来 90 天","未来一年"});range.SelectedIndex=1;Action load=()=>{g.Rows.Clear();foreach(var r in Workshop.Reminders(Store.Data,DateTime.Today,new[]{30,90,366}[range.SelectedIndex])){int row=g.Rows.Add(r.Date.ToString("yyyy-MM-dd"),r.Kind,Store.Name(r.PersonId),r.Years,(r.Date-DateTime.Today).Days+" 天");g.Rows[row].Tag=r.PersonId;}};range.SelectedIndexChanged+=(s,e)=>load();Tools(p,new InputFrame(range){Width=140,Height=39},Ui.Button("编辑成员",()=>{if(Key(g)!="")edit(Key(g));}),Ui.Button("导出提醒",()=>{string f=Ui.SavePath("CSV 清单|*.csv","生日与忌日提醒.csv");if(f!=null)WriteCsv(f,new[]{new[]{"纪念日期","类型","姓名","周年"}}.Concat(Workshop.Reminders(Store.Data,DateTime.Today,new[]{30,90,366}[range.SelectedIndex]).Select(x=>new[]{x.Date.ToString("yyyy-MM-dd"),x.Kind,Store.Name(x.PersonId),x.Years.ToString()})));}),Ui.Label("按公历；闰日在平年取 2 月最后一天。",9));p.Controls.Add(g);g.BringToFront();load();}
  void TaskTab(){var p=Page("编修待办");var g=Ui.Grid();Ui.Columns(g,"状态","截止日","待办标题","关联成员","线索说明");foreach(var t in Store.Data.Tasks.OrderBy(x=>x.Done).ThenBy(x=>x.Due==""?"9999":x.Due)){string state=t.Done?"已完成":t.Due!=""&&Store.DateStart(t.Due)<DateTime.Today?"已逾期":"待处理";int r=g.Rows.Add(state,t.Due,t.Title,Store.Name(t.PersonId),t.Notes);g.Rows[r].Tag=t.Id;}Tools(p,Ui.Button("添加待办",()=>{using(var w=new TaskEditor(null))if(w.ShowDialog(this)==DialogResult.OK)RefreshTabs();},true),Ui.Button("编辑",()=>{var t=Store.Data.Tasks.Find(x=>x.Id==Key(g));if(t!=null)using(var w=new TaskEditor(t))if(w.ShowDialog(this)==DialogResult.OK)RefreshTabs();}),Ui.Button("完成 / 重开",()=>{var d=Workshop.Clone();var t=d.Tasks.Find(x=>x.Id==Key(g));if(t!=null){t.Done=!t.Done;Store.Commit(d);RefreshTabs();}}),Ui.Button("删除待办",()=>{if(Key(g)!=""&&Ui.Confirm("删除选中的编修待办？")){var d=Workshop.Clone();d.Tasks.RemoveAll(x=>x.Id==Key(g));Store.Commit(d);RefreshTabs();}}));p.Controls.Add(g);g.BringToFront();}
 }
}
